export const GLOSSARY_SHARD = Object.freeze({"all-time-high":{"slug":"all-time-high","cat":"basics","en":"All-time high (ATH)","contentLocale":"vi","term":"Đỉnh lịch sử (All-time high - ATH)","aka":["ATH","all-time high","đỉnh mọi thời đại"],"short":"Đỉnh lịch sử (all-time high, ATH) là mức giá cao nhất mà một tài sản từng đạt được kể từ khi bắt đầu giao dịch, thường được tính theo một đồng tiền định giá như USD hoặc USDT.","body":[["Khi giá phá ATH, không có ai đang lỗ ở vùng giá phía trên, nên không có kháng cự từ người muốn bán hòa vốn. Đây là lý do giá đôi khi tăng nhanh sau khi vượt đỉnh. Nhưng vùng ATH cũng là nơi nhiều người ",["chốt lời","take-profit"]," và ",["FOMO","fomo"]," lên cao."],["ATH có thể khác nhau giữa các sàn và ",["cặp giao dịch","trading-pair"],", vì mỗi sàn có ",["sổ lệnh","order-book"]," riêng; một cú râu nến ngắn trên một sàn có thể tạo ATH mà sàn khác không có. ATH tính theo USD cũng khác ATH tính theo VND hay theo ",["BTC","bitcoin"],"."],["Một chỉ số hay dùng là mức giảm so với ATH (drawdown). ",["Altcoin","altcoin"]," giảm 90% từ ATH thì phải tăng gấp 10 lần mới quay lại đỉnh cũ, và nhiều đồng không bao giờ làm được."]],"example":"Một coin lập ATH ở 4 USDT rồi giảm còn 0,8 USDT, tức giảm 80% so với đỉnh. Nếu bạn mua ở 0,8 USDT với 400 USDT, bạn nhận 500 coin. Để quay về ATH, giá phải tăng 400% (gấp 5 lần), khi đó phần của bạn trị giá 2.000 USDT. Nếu giá chỉ hồi lên 1,2 USDT, đó đã là mức tăng 50% từ đáy, dù vẫn thấp hơn ATH 70%.","mistakes":["Nghĩ rằng coin đã giảm xa ATH thì chắc chắn sẽ quay lại đỉnh cũ.","Mua đuổi khi giá vừa phá ATH mà không có kế hoạch cắt lỗ.","So sánh ATH giữa các nguồn dữ liệu mà không để ý chúng dùng sàn và đồng định giá khác nhau."],"faq":[{"q":"ATH nghĩa là gì trong crypto?","a":"ATH là viết tắt của all-time high, mức giá cao nhất từng đạt. Ngược lại, ATL (all-time low) là mức giá thấp nhất từng có."},{"q":"Giá phá ATH có phải tín hiệu mua không?","a":"Không tự động. Phá ATH cho thấy lực mua mạnh nhưng cũng là vùng nhiều người chốt lời, nên vẫn cần kế hoạch rủi ro như mọi lệnh khác."}],"title":"ATH là gì? Đỉnh lịch sử (all-time high)","description":"ATH là gì, vì sao giá hay tăng nhanh khi phá đỉnh, ATH khác nhau giữa các sàn ra sao và cách tính mức giảm từ đỉnh.","related":[["bull-market","Thị trường tăng giá (Bull market)","Thị trường tăng giá (bull market) là giai đoạn giá tài sản đi lên kéo dài, đi kèm tâm lý lạc quan, khối lượng giao dịch tăng và dòng tiền mới đổ vào thị trường."],["fomo","FOMO (sợ bỏ lỡ)","FOMO (fear of missing out) là nỗi sợ bỏ lỡ cơ hội, khiến người giao dịch vội mua một tài sản đang tăng nóng mà không có kế hoạch, thường ở mức giá đã cao."],["volatility","Biến động giá (Volatility)","Biến động giá (volatility) là mức độ và tốc độ thay đổi giá của một tài sản trong một khoảng thời gian; biến động càng cao thì giá dao động lên xuống càng mạnh."],["support-and-resistance","Hỗ trợ và kháng cự (Support và Resistance)","Hỗ trợ và kháng cự là các vùng giá mà trước đây giá thường dừng giảm (hỗ trợ) hoặc dừng tăng (kháng cự), do lực mua hoặc lực bán tập trung ở đó."]],"lesson":null,"coin":null,"tool":"/coins","cta":false},"coin-margined-futures":{"slug":"coin-margined-futures","cat":"derivatives","en":"Coin-margined (inverse) futures","contentLocale":"vi","term":"Hợp đồng ký quỹ bằng coin (Coin-M)","aka":["Coin-M","hợp đồng nghịch đảo","inverse futures","coin-margined"],"short":"Hợp đồng ký quỹ bằng coin (Coin-M, hay hợp đồng nghịch đảo) là hợp đồng tương lai mà ký quỹ và lãi lỗ được tính bằng chính đồng coin cơ sở, ví dụ BTC, thay vì USDT.","body":[["Với Coin-M, bạn nạp ",["BTC","bitcoin"]," làm ký quỹ để giao dịch hợp đồng BTC/USD. Hợp đồng thường có mệnh giá cố định theo USD, ví dụ 100 USD mỗi hợp đồng, còn lãi lỗ được trả bằng BTC. Đây là lý do nó được gọi là hợp đồng nghịch đảo: giá trị tính bằng coin thay đổi ngược chiều với giá."],["Điểm cần hiểu là ký quỹ của bạn cũng ",["biến động giá","volatility"],". Khi bạn long bằng ký quỹ BTC, giá giảm khiến bạn vừa lỗ vị thế vừa mất giá trị ký quỹ, nên rủi ro tăng gấp đôi. Ngược lại, short đúng bằng lượng BTC đang giữ giúp khóa giá trị theo USD."],["Coin-M phù hợp với thợ đào và người giữ coin lâu dài muốn ",["phòng hộ","hedging"]," mà không đổi sang ",["stablecoin","stablecoin"],". Mệnh giá hợp đồng và danh sách cặp khác nhau tùy sàn."]],"example":["Giả sử bạn có 1 BTC khi giá 50.000 USD và muốn khóa giá trị. Bạn short 500 hợp đồng Coin-M BTC/USD mệnh giá 100 USD, tổng 50.000 USD, ",["đòn bẩy","leverage"]," 1x. Nếu BTC giảm xuống 40.000 USD, lợi nhuận short là 50.000/40.000 - 50.000/50.000 = 1,25 - 1 = 0,25 BTC. Tổng bạn có 1,25 BTC × 40.000 = 50.000 USD, giá trị theo USD gần như không đổi trước phí và funding."],"mistakes":["Long với đòn bẩy cao trên Coin-M mà quên rằng ký quỹ cũng mất giá khi giá giảm.","Tính lãi lỗ như hợp đồng USDT trong khi công thức nghịch đảo không tuyến tính.","Nhầm mệnh giá hợp đồng với số lượng coin."],"faq":[{"q":"Coin-M và USDT-M khác nhau thế nào?","a":"Coin-M dùng coin làm ký quỹ và trả lãi lỗ bằng coin. USDT-M dùng USDT, lãi lỗ tuyến tính và dễ tính hơn."},{"q":"Vì sao gọi là hợp đồng nghịch đảo?","a":"Vì lãi lỗ tính bằng coin theo công thức 1/giá, nên giá trị đo bằng coin thay đổi ngược chiều với giá USD."}],"title":"Hợp đồng Coin-M là gì? Hợp đồng ký quỹ bằng coin","description":"Hợp đồng ký quỹ bằng coin (Coin-M) là gì, cách tính lãi lỗ nghịch đảo và khi nào nên dùng thay cho USDT-M.","related":[["usdt-margined-futures","Hợp đồng ký quỹ bằng USDT (USDT-M)","Hợp đồng ký quỹ bằng USDT (USDT-M, hay hợp đồng tuyến tính) là hợp đồng tương lai mà ký quỹ, lãi lỗ và phí đều tính bằng USDT."],["perpetual-futures","Hợp đồng tương lai vĩnh cửu (Perpetual)","Hợp đồng tương lai vĩnh cửu (perpetual) là hợp đồng tương lai không có ngày đáo hạn, dùng cơ chế funding rate để giữ giá hợp đồng bám sát giá spot."],["unrealized-pnl","Lãi lỗ chưa thực hiện (Unrealized PnL)","Lãi lỗ chưa thực hiện (unrealized PnL) là khoản lãi hoặc lỗ trên giấy của một vị thế đang mở, tính theo giá hiện tại, và chỉ trở thành lãi lỗ thật khi bạn đóng vị thế."],["hedging","Phòng hộ (Hedging)","Phòng hộ (hedging) là việc mở một vị thế ngược chiều để giảm rủi ro biến động giá của tài sản bạn đang nắm giữ, đổi lại bằng việc hạn chế phần lợi nhuận."]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"Giao ngay và tương lai: bạn không mua cùng một thứ"},"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"hedging":{"slug":"hedging","cat":"derivatives","en":"Hedging","contentLocale":"vi","term":"Phòng hộ (Hedging)","aka":["hedging","hedge","phòng hộ rủi ro"],"short":"Phòng hộ (hedging) là việc mở một vị thế ngược chiều để giảm rủi ro biến động giá của tài sản bạn đang nắm giữ, đổi lại bằng việc hạn chế phần lợi nhuận.","body":[["Cách phổ biến nhất là short ",["hợp đồng tương lai","futures-contract"]," với lượng tương đương số coin đang giữ trên spot. Khi giá giảm, lãi từ short bù lỗ trên spot; khi giá tăng, lỗ từ short ăn bớt lãi trên spot. Giá trị danh mục tính theo USD gần như được khóa lại."],["Bạn cũng có thể phòng hộ một phần, ví dụ chỉ 50% lượng coin, hoặc dùng ",["quyền chọn","options"]," bán (put) để giới hạn lỗ mà vẫn giữ lợi nhuận khi giá tăng, đổi lại phải trả phí quyền chọn."],["Phòng hộ có chi phí: phí giao dịch, funding hoặc basis, và rủi ro ",["thanh lý","liquidation"]," trên ",["vị thế short","long-and-short"]," nếu ký quỹ không đủ khi giá tăng mạnh. Một vị thế phòng hộ bị thanh lý sẽ để lại phần spot không được bảo vệ."]],"example":["Giả sử bạn giữ 10 ",["ETH","ethereum"],", giá 3.000 ",["USDT","usdt"],", tổng 30.000 USDT. Bạn lo giá giảm trong tháng tới nên short 10 ETH perpetual. ETH giảm còn 2.500: spot lỗ 5.000 USDT, short lãi 5.000 USDT. Nếu funding trung bình +0,01% mỗi 8 giờ, phe short nhận khoảng 3 × 30 × 0,01% × 30.000 = 270 USDT trong 30 ngày (tính gần đúng trên giá trị ban đầu). Nếu funding âm, bạn phải trả khoản tương tự."],"mistakes":["Short phòng hộ với đòn bẩy cao, để rồi vị thế short bị thanh lý khi giá tăng mạnh.","Quên đóng vị thế phòng hộ khi đã bán phần spot.","Không tính funding hoặc phí quyền chọn vào chi phí phòng hộ."],"faq":[{"q":"Hedging trong crypto là gì?","a":"Là mở vị thế ngược chiều, thường là short futures, để giảm rủi ro giá của coin bạn đang giữ. Bạn đổi một phần lợi nhuận tiềm năng lấy sự ổn định."},{"q":"Phòng hộ bằng futures hay quyền chọn tốt hơn?","a":"Futures rẻ và đơn giản nhưng cắt cả phần lãi khi giá tăng. Quyền chọn put giữ phần lãi nhưng phải trả phí quyền chọn trước."}],"title":"Hedging là gì? Cách phòng hộ rủi ro trong crypto","description":"Phòng hộ (hedging) là gì, cách dùng futures hoặc quyền chọn để giảm rủi ro giá và các chi phí cần tính trước.","related":[["short-selling","Bán khống (Short selling)","Bán khống là việc bán một tài sản bạn không sở hữu, bằng cách vay hoặc dùng hợp đồng phái sinh, với kỳ vọng mua lại ở giá thấp hơn để kiếm lời."],["perpetual-futures","Hợp đồng tương lai vĩnh cửu (Perpetual)","Hợp đồng tương lai vĩnh cửu (perpetual) là hợp đồng tương lai không có ngày đáo hạn, dùng cơ chế funding rate để giữ giá hợp đồng bám sát giá spot."],["options","Quyền chọn crypto (Options)","Quyền chọn crypto là hợp đồng cho người mua quyền, nhưng không bắt buộc, mua (call) hoặc bán (put) một tài sản ở mức giá định trước trong hoặc tại một thời điểm định trước."],["portfolio-margin","Ký quỹ danh mục (Portfolio margin)","Ký quỹ danh mục là chế độ tính ký quỹ dựa trên rủi ro tổng thể của cả danh mục, cho phép các vị thế phòng hộ lẫn nhau được giảm yêu cầu ký quỹ."]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"Giao ngay và tương lai: bạn không mua cùng một thứ"},"coin":null,"tool":null,"cta":false},"options":{"slug":"options","cat":"derivatives","en":"Crypto options","contentLocale":"vi","term":"Quyền chọn crypto (Options)","aka":["options","quyền chọn","call","put"],"short":"Quyền chọn crypto là hợp đồng cho người mua quyền, nhưng không bắt buộc, mua (call) hoặc bán (put) một tài sản ở mức giá định trước trong hoặc tại một thời điểm định trước.","body":["Người mua quyền chọn trả một khoản phí gọi là premium. Mức lỗ tối đa của người mua là khoản premium đó. Người bán quyền chọn nhận premium nhưng chịu nghĩa vụ thực hiện nếu người mua yêu cầu, nên rủi ro của họ có thể lớn hơn nhiều.",["Giá thực hiện (strike), ngày đáo hạn và ",["độ biến động","volatility"]," kỳ vọng quyết định giá premium. Biến động càng cao, quyền chọn càng đắt. Quyền chọn crypto phần lớn là kiểu châu Âu, chỉ thực hiện vào ngày đáo hạn, và tất toán bằng tiền."],["Quyền chọn được dùng để ",["phòng hộ","hedging"],", ví dụ mua put để bảo vệ ",["BTC","bitcoin"]," đang giữ, hoặc để thu premium. Deribit là sàn quyền chọn crypto lớn, và nhiều sàn khác như OKX, Bybit, Binance cũng có quyền chọn. Sản phẩm ",["đầu tư kép","dual-investment"]," trên sàn thực chất dựa trên việc bán quyền chọn."]],"example":["Giả sử BTC ở 60.000 ",["USDT","usdt"]," và bạn mua 1 quyền chọn call strike 65.000, đáo hạn sau 30 ngày, premium 1.500 USDT. Nếu đến ngày đáo hạn BTC ở 70.000, bạn nhận 70.000 - 65.000 = 5.000 USDT, lãi ròng 3.500 USDT. Nếu BTC ở 64.000 hoặc thấp hơn, quyền chọn hết hạn vô giá trị và bạn mất 1.500 USDT premium. Điểm hòa vốn là 66.500 USDT."],"mistakes":["Mua quyền chọn rẻ, xa giá hiện tại và nghĩ chúng dễ sinh lời.","Bán quyền chọn để thu premium mà không hiểu rủi ro khi giá chạy mạnh.","Quên rằng giá trị quyền chọn giảm dần theo thời gian khi gần đáo hạn."],"faq":[{"q":"Quyền chọn call và put khác nhau thế nào?","a":"Call là quyền mua ở giá định trước, có lợi khi giá tăng. Put là quyền bán ở giá định trước, có lợi khi giá giảm."},{"q":"Người mua quyền chọn có thể mất bao nhiêu?","a":"Tối đa là khoản premium đã trả. Người bán quyền chọn thì có thể lỗ nhiều hơn khoản premium nhận được."}],"title":"Quyền chọn crypto (options) là gì? Call và put","description":"Quyền chọn crypto là gì, call và put khác nhau thế nào, premium được tính ra sao và cách dùng options để phòng hộ.","related":[["futures-contract","Hợp đồng tương lai (Futures)","Hợp đồng tương lai là thỏa thuận mua hoặc bán một tài sản theo giá xác định, cho phép bạn kiếm lời từ biến động giá mà không cần sở hữu tài sản thật."],["hedging","Phòng hộ (Hedging)","Phòng hộ (hedging) là việc mở một vị thế ngược chiều để giảm rủi ro biến động giá của tài sản bạn đang nắm giữ, đổi lại bằng việc hạn chế phần lợi nhuận."],["volatility","Biến động giá (Volatility)","Biến động giá (volatility) là mức độ và tốc độ thay đổi giá của một tài sản trong một khoảng thời gian; biến động càng cao thì giá dao động lên xuống càng mạnh."],["dual-investment","Đầu tư kép (dual investment)","Đầu tư kép là sản phẩm có cấu trúc cho lợi suất cao trong thời gian ngắn, nhưng khi đáo hạn bạn có thể nhận lại tài sản ban đầu hoặc một tài sản khác tùy giá so với giá mục tiêu."]],"lesson":null,"coin":null,"tool":"/topics/derivatives","cta":false},"custodial-wallet":{"slug":"custodial-wallet","cat":"wallets-security","en":"Custodial wallet","contentLocale":"vi","term":"Ví lưu ký (Custodial wallet)","aka":["custodial wallet","ví custodial","ví trên sàn"],"short":"Ví lưu ký là ví mà một bên thứ ba, thường là sàn giao dịch, giữ khóa riêng tư thay bạn; bạn truy cập tài sản bằng tài khoản và mật khẩu thay vì seed phrase.","body":[["Khi bạn nạp coin vào ",["sàn tập trung","centralized-exchange"],", coin đi vào ví do sàn kiểm soát. Số dư bạn thấy trong tài khoản là ghi nhận nội bộ của sàn. Bạn có thể giao dịch nhanh, quên mật khẩu vẫn khôi phục được, nhưng mọi lệnh rút đều cần sàn chấp thuận."],["Rủi ro chính là rủi ro đối tác: sàn có thể bị hack, đóng băng tài khoản theo yêu cầu pháp lý, tạm dừng rút tiền, hoặc phá sản. ",["Bằng chứng dự trữ (proof of reserves)","proof-of-reserves"]," giúp kiểm tra phần nào việc sàn giữ đủ tài sản, nhưng không phải bảo đảm tuyệt đối."],["Ví lưu ký phù hợp cho số tiền bạn đang giao dịch tích cực. Với tài sản giữ lâu dài, nhiều người chọn ",["ví tự lưu ký","non-custodial-wallet"],". Mức độ bảo vệ và quy định pháp lý khác nhau theo sàn và quốc gia."]],"example":["Giả sử bạn có 8.000 ",["USDT","usdt"]," tài sản crypto. Bạn để 2.000 USDT trên sàn để giao dịch hàng tuần và chuyển 6.000 USDT sang ví tự lưu ký. Nếu một ngày sàn tạm dừng rút tiền, chỉ 25% tài sản của bạn bị kẹt thay vì 100%. Đổi lại, mỗi lần muốn giao dịch phần còn lại, bạn phải nạp lại và trả ",["phí mạng","gas-fee"],"."],"mistakes":["Để toàn bộ tài sản giữ lâu dài trên một sàn duy nhất.","Không bật xác thực hai lớp và danh sách địa chỉ rút tiền trên tài khoản sàn.","Nghĩ rằng số dư trên sàn là coin của mình nằm trên blockchain dưới tên mình."],"faq":[{"q":"Ví lưu ký khác ví tự lưu ký thế nào?","a":"Ví lưu ký do bên thứ ba giữ khóa, bạn đăng nhập bằng tài khoản. Ví tự lưu ký do bạn tự giữ khóa qua seed phrase và tự chịu trách nhiệm."},{"q":"Để tiền trên sàn có an toàn không?","a":"Phụ thuộc vào độ uy tín và bảo mật của sàn cũng như của tài khoản bạn. Nhiều người chỉ để trên sàn phần tiền đang giao dịch."}],"title":"Ví lưu ký (custodial wallet) là gì?","description":"Ví lưu ký là gì, vì sao tài khoản trên sàn là ví custodial, các rủi ro đối tác và khi nào nên chuyển sang ví tự lưu ký.","related":[["non-custodial-wallet","Ví phi lưu ký (Non-custodial wallet)","Ví phi lưu ký là loại ví crypto mà bạn tự giữ khóa riêng tư và cụm từ khôi phục, nên chỉ bạn mới có quyền ký giao dịch và di chuyển tài sản."],["centralized-exchange","Sàn giao dịch tập trung (CEX)","Sàn giao dịch tập trung (CEX) là nền tảng do một công ty vận hành, giữ tài sản của người dùng và khớp lệnh mua bán trên sổ lệnh nội bộ, như Binance, OKX, Bybit hay Bitget."],["proof-of-reserves","Bằng chứng dự trữ (Proof of reserves)","Bằng chứng dự trữ là báo cáo sàn công bố để chứng minh họ đang nắm giữ đủ tài sản on-chain tương ứng với số dư khách hàng, thường kèm cách để từng người tự kiểm tra."],["crypto-wallet","Ví tiền mã hóa (Crypto wallet)","Ví tiền mã hóa là phần mềm hoặc thiết bị quản lý khóa riêng tư của bạn, cho phép bạn nhận, gửi và ký giao dịch với tài sản crypto trên blockchain."]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"Coin của tôi ở đâu: Sàn giao dịch và ví khác nhau thế nào?"},"coin":null,"tool":null,"cta":false},"on-chain-analysis":{"slug":"on-chain-analysis","cat":"onchain","en":"On-chain analysis","contentLocale":"vi","term":"Phân tích on-chain","aka":["on-chain analysis","phân tích dữ liệu on-chain","phân tích chuỗi"],"short":"Phân tích on-chain là việc đọc dữ liệu công khai trên blockchain như giao dịch, số dư ví và dòng tiền ra vào sàn để hiểu hành vi của người tham gia thị trường.","body":[["Mọi giao dịch trên ",["blockchain","blockchain"]," công khai đều được ghi lại và ai cũng xem được. Nhà phân tích gom dữ liệu này thành chỉ số: ",["số địa chỉ hoạt động","active-addresses"],", lượng coin chảy vào và ra khỏi sàn, hành vi của ",["ví cá voi","whale"],", lượng coin lâu ngày không di chuyển, hay tổng phí giao dịch."],["Khác với phân tích kỹ thuật chỉ nhìn giá và khối lượng trên biểu đồ, phân tích on-chain nhìn vào việc ai đang thực sự giữ và di chuyển tài sản. Ví dụ, lượng lớn ",["BTC","bitcoin"]," chuyển ",["lên sàn","token-listing"]," có thể là dấu hiệu chuẩn bị bán, nhưng cũng có thể là sàn tự chuyển nội bộ."],["Hạn chế lớn là việc gắn nhãn ví không bao giờ chính xác tuyệt đối, và giao dịch trên ",["sàn tập trung","centralized-exchange"]," diễn ra ngoài chuỗi nên không hiện lên. Vì vậy dữ liệu on-chain nên được dùng như một góc nhìn bổ sung, kết hợp với bối cảnh thị trường."]],"example":"Giả sử trong một tuần, dữ liệu cho thấy 25.000 BTC rời khỏi các ví sàn và chỉ 15.000 BTC chảy vào, tức dòng ròng âm 10.000 BTC. Nếu BTC giá 60.000 USD, khoảng 600 triệu USD đã rời sàn. Nhiều người hiểu đây là nhà đầu tư rút coin về ví để giữ lâu dài. Nhưng trước khi kết luận, bạn cần kiểm tra xem có phải một sàn đang chuyển coin sang ví lưu ký mới hay không.","mistakes":["Coi một chỉ số on-chain duy nhất là tín hiệu mua bán chắc chắn.","Tin hoàn toàn vào nhãn ví do công cụ gắn mà không xem lại lịch sử giao dịch.","Quên rằng giao dịch nội bộ trên sàn tập trung không xuất hiện trên chuỗi."],"faq":[{"q":"Phân tích on-chain có dự đoán được giá không?","a":"Không thể dự đoán chắc chắn. Nó giúp bạn hiểu dòng tiền và hành vi người nắm giữ, từ đó có thêm bối cảnh cho quyết định."},{"q":"Người mới nên bắt đầu với chỉ số on-chain nào?","a":"Dòng tiền ròng vào ra sàn, số địa chỉ hoạt động và lượng stablecoin trên sàn là ba chỉ số dễ hiểu. Hãy theo dõi xu hướng nhiều tuần thay vì phản ứng với một ngày."}],"title":"Phân tích on-chain là gì? Cách đọc dữ liệu blockchain","description":"Phân tích on-chain dùng dữ liệu blockchain công khai để hiểu dòng tiền và hành vi ví. Tìm hiểu chỉ số chính và hạn chế.","related":[["exchange-netflow","Dòng tiền vào ra sàn (exchange netflow)","Dòng tiền vào ra sàn là chỉ số on-chain đo lượng coin chuyển vào ví sàn trừ đi lượng coin rút ra khỏi sàn trong một khoảng thời gian."],["whale","Cá voi (Whale)","Cá voi (whale) là cá nhân hoặc tổ chức nắm giữ lượng lớn một loại tiền mã hóa, đủ để các giao dịch của họ có thể ảnh hưởng tới giá hoặc thanh khoản."],["active-addresses","Địa chỉ hoạt động (active addresses)","Địa chỉ hoạt động là số địa chỉ ví riêng biệt có gửi hoặc nhận giao dịch thành công trên một blockchain trong một khoảng thời gian, thường là một ngày."],["block-explorer","Block explorer (trình khám phá khối)","Block explorer là trang web cho phép bạn tra cứu mọi giao dịch, địa chỉ ví và khối trên một blockchain, giống như công cụ tra cứu sao kê công khai của mạng đó."]],"lesson":null,"coin":null,"tool":"/onchain","cta":false},"grid-trading-bot":{"slug":"grid-trading-bot","cat":"exchange-features","en":"Grid trading bot","contentLocale":"vi","term":"Bot giao dịch lưới (grid bot)","aka":["grid bot","bot lưới","grid trading","giao dịch lưới"],"short":"Bot giao dịch lưới là công cụ tự động đặt sẵn nhiều lệnh mua và bán ở các mức giá cách đều trong một vùng, để kiếm lời từ những lần giá dao động lên xuống.","body":[["Bạn chọn giá thấp nhất, giá cao nhất và số lưới. Bot chia vùng giá thành các nấc và đặt ",["lệnh giới hạn","limit-order"]," mua ở các nấc dưới giá hiện tại, lệnh bán ở các nấc trên. Mỗi lần giá giảm qua một nấc rồi tăng trở lại, bot mua thấp bán cao và ghi nhận một khoản lời nhỏ."],["Bot lưới hiệu quả nhất khi thị trường đi ngang và dao động nhiều. Nếu giá tăng vượt vùng, bot đã bán hết và bạn bỏ lỡ phần tăng thêm. Nếu giá giảm thủng vùng, bot giữ toàn coin đang lỗ. Bot lưới trên ",["hợp đồng tương lai","futures-contract"]," có thêm ",["đòn bẩy","leverage"]," nên có thể ",["bị thanh lý","liquidation"],"."],"Hầu hết sàn lớn cung cấp bot lưới spot và futures, có chế độ AI gợi ý tham số. Phí giao dịch ở mỗi lần khớp lệnh có thể ăn mòn lợi nhuận nếu khoảng cách lưới quá hẹp."],"example":["Giả sử bạn chạy bot lưới ",["ETH","ethereum"]," với vùng 2.000 đến 3.000 ",["USDT","usdt"],", 10 lưới, mỗi nấc cách nhau 100 USDT và đặt khoảng 100 USDT vào mỗi nấc. Giá giảm từ 2.500 xuống 2.400, bot mua khoảng 0,0417 ETH. Giá hồi lên 2.500, bot bán ra và lời khoảng 4,17 USDT. Trừ phí 0,1% cho mỗi chiều, khoảng 0,2 USDT, lợi nhuận mỗi vòng còn khoảng 3,96 USDT."],"mistakes":["Đặt vùng giá quá hẹp, giá thoát khỏi vùng chỉ sau vài giờ.","Chia quá nhiều lưới nên lợi nhuận mỗi vòng không đủ bù phí.","Chạy bot lưới futures với đòn bẩy cao mà không tính giá thanh lý."],"faq":[{"q":"Bot lưới có lỗ được không?","a":"Có. Khi giá giảm thủng vùng, bạn giữ coin ở giá vốn cao hơn giá thị trường. Lợi nhuận lưới tích lũy có thể không bù được khoản lỗ này."},{"q":"Nên chọn bao nhiêu lưới?","a":"Khoảng cách giữa hai nấc nên lớn hơn nhiều lần tổng phí hai chiều. Hãy chọn số lưới sao cho mỗi vòng có lợi nhuận rõ ràng sau phí."}],"title":"Bot giao dịch lưới là gì? Cách grid bot kiếm lời","description":"Grid bot đặt lệnh mua bán tự động trong một vùng giá. Hiểu cách thiết lập lưới, khi nào hiệu quả và rủi ro khi giá thoát vùng.","related":[["dollar-cost-averaging","DCA (Trung bình giá)","DCA (dollar-cost averaging) là chiến lược mua một số tiền cố định của một tài sản theo lịch đều đặn, bất kể giá lên hay xuống, để làm mềm tác động của biến động giá."],["copy-trading","Copy trade (sao chép giao dịch)","Copy trade là tính năng cho phép bạn tự động sao chép các lệnh của một nhà giao dịch khác, gọi là trader dẫn dắt, theo tỷ lệ vốn mà bạn phân bổ."],["volatility","Biến động giá (Volatility)","Biến động giá (volatility) là mức độ và tốc độ thay đổi giá của một tài sản trong một khoảng thời gian; biến động càng cao thì giá dao động lên xuống càng mạnh."],["limit-order","Lệnh giới hạn (Limit order)","Lệnh giới hạn (limit order) là lệnh mua hoặc bán ở mức giá bạn chỉ định hoặc tốt hơn; lệnh chỉ khớp khi thị trường chạm mức giá đó, nếu không sẽ nằm chờ trong sổ lệnh."]],"lesson":null,"coin":null,"tool":null,"cta":true}});
